/**
 * Auto-discovers src/apps/<app>/manifest.ts and writes src/platform/apps/registry.generated.ts.
 * The generated file is gitignored, so app PRs never touch a shared registry file.
 * Runs on postinstall, dev, build, lint, typecheck and test.
 */
import { readdirSync, existsSync, writeFileSync, mkdirSync } from "node:fs";
import path from "node:path";

const root = path.resolve(import.meta.dirname, "..");
const appsDir = path.join(root, "src", "apps");
const out = path.join(root, "src", "platform", "apps", "registry.generated.ts");

const ids = existsSync(appsDir)
  ? readdirSync(appsDir, { withFileTypes: true })
      .filter((d) => d.isDirectory() && existsSync(path.join(appsDir, d.name, "manifest.ts")))
      .map((d) => d.name)
      .sort()
  : [];

const lines = [
  "// AUTO-GENERATED by scripts/generate-registry.ts. Do not edit. Do not commit.",
  'import type { AppManifest } from "./define";',
  ...ids.map((id, i) => `import m${i} from "@/apps/${id}/manifest";`),
  "",
  `export const manifests: AppManifest[] = [${ids.map((_, i) => `m${i}`).join(", ")}];`,
  "",
];
mkdirSync(path.dirname(out), { recursive: true });
writeFileSync(out, lines.join("\n"));
console.log(`registry: ${ids.length} app(s): ${ids.join(", ") || "(none)"}`);
